package com.quincaisoft.tenders.domain;
public final class TenderRules {private TenderRules(){} public static long amount(String s,boolean zero){if(s==null||!s.matches("0|[1-9][0-9]*"))throw new IllegalArgumentException("Integral nonnegative XAF string required");long n=Long.parseLong(s);if(!zero&&n==0)throw new IllegalArgumentException("Amount must be positive");return n;}public static long remaining(long original,long allocated,long refunded){long n=Math.subtractExact(Math.subtractExact(original,allocated),refunded);if(n<0)throw new IllegalStateException("Deposit conservation violated");return n;}}
